using System.Text.Json.Nodes;

namespace SplashTheMusical.Upstream;

/// <summary>Writes <c>MermaidCompatibility</c>, whose version is the mermaid that tools/oracle/package-lock.json installs.</summary>
public static class CompatibilityWriter
{
	public const string FileName = "MermaidCompatibility.g.cs";

	/// <summary>The folder of the generated file, below the repository.</summary>
	public static string Folder(string repository) => Path.Combine(repository, "src", "SplashTheMusical", "Generated");

	/// <summary>The version of <c>node_modules/mermaid</c> in the oracle's lock file.</summary>
	public static string LockedVersion(string repository)
	{
		var lockFile = JsonNode.Parse(File.ReadAllText(Path.Combine(repository, "tools", "oracle", "package-lock.json")))!;
		return lockFile["packages"]?["node_modules/mermaid"]?["version"]?.GetValue<string>()
			?? throw new InvalidOperationException("tools/oracle/package-lock.json has no node_modules/mermaid version");
	}

	public static string Write(string repository) =>
		$$"""
		// <auto-generated>
		// Generated by tools/SplashTheMusical.Upstream from the mermaid version in tools/oracle/package-lock.json.
		// Run mise run upstream-compatibility to rewrite it.
		// </auto-generated>

		namespace SplashTheMusical;

		/// <summary>The mermaid.js release STM was verified against.</summary>
		public static class MermaidCompatibility
		{
			/// <summary>The version of mermaid.js that <c>tools/oracle</c> pins. The <c>info</c> diagram draws it.</summary>
			public const string MermaidJsVersion = "{{LockedVersion(repository)}}";
		}

		""".ReplaceLineEndings("\n");
}
